package com.gamehubstore.order_mscv.controllers;
import com.gamehubstore.order_mscv.exceptions.OrderException; import feign.FeignException; import org.slf4j.*; import org.springframework.http.*; import org.springframework.validation.FieldError; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {private static final Logger log=LoggerFactory.getLogger(ApiExceptionHandler.class);
 @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException ex){Map<String,String> fields=new LinkedHashMap<>();for(FieldError e:ex.getBindingResult().getFieldErrors())fields.put(e.getField(),e.getDefaultMessage());log.warn("Validación de orden fallida: {}",fields);return ResponseEntity.badRequest().body(Map.of("error","Solicitud inválida","fields",fields));}
 @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class,OrderException.class}) public ResponseEntity<Map<String,String>> business(RuntimeException ex){log.warn("Regla de orden: {}",ex.getMessage());return ResponseEntity.unprocessableEntity().body(Map.of("error",Objects.toString(ex.getMessage(),"Regla de negocio incumplida")));}
 @ExceptionHandler(FeignException.class) public ResponseEntity<Map<String,String>> dependency(FeignException ex){log.error("Dependencia remota de órdenes no disponible: status={}",ex.status());return ResponseEntity.status(HttpStatus.BAD_GATEWAY).body(Map.of("error","No fue posible validar una dependencia de la orden"));}
}
